/**
 * 본문 키워드를 분석하여 가장 적합한 7대 테마 클러스터를 판별한다.
 * 단순 단일 if문이 아닌 단어별 출현 빈도와 전문 키워드 가중치를 누적 합산한다.
 */
export function detectThemeCluster(text = '') {
  const t = text.toLowerCase();

  const scores = {
    mobility: 0,
    shopping: 0,
    fitness: 0,
    tech_business: 0,
    food_cooking: 0,
    finance_life: 0,
    outdoor_nature: 0
  };

  const countMatches = (regex) => (t.match(regex) || []).length;

  // 1. 모빌리티 / 차량 / 이동 (최우선 도메인 키워드)
  scores.mobility += countMatches(/(주유소|알뜰주유소|주유|휘발유|경유|유가|기름값|세차장|셀프\s*세차|드라이브|고속도로|휴게소|전기차|충전소)/g) * 15;
  scores.mobility += countMatches(/(자동차|차량|엔진|타이어|내비|운전|차박|톨게이트|주차|교통)/g) * 5;

  // 2. 마트 / 쇼핑 / 생활 소비
  scores.shopping += countMatches(/(이마트|홈플러스|코스트코|대형마트|마트|전통시장|장보기|식재료|삼겹살|장바구니|카트|신선식품|특가|세일|할인)/g) * 15;
  scores.shopping += countMatches(/(구매|결제|쇼핑|편의점|1\+1|원플러스원|영수증|득템|최저가|쿠폰)/g) * 5;

  // 3. 피트니스 / 운동 / 활력
  scores.fitness += countMatches(/(러닝|마라톤|조깅|헬스장|피트니스|우레탄\s*트랙|달리기|완주|스쿼트|덤벨)/g) * 15;
  scores.fitness += countMatches(/(운동|체력|스트레칭|바이크|자전거|한강|워밍업|근력|심박수|땀|칼로리|단백질|프로틴)/g) * 5;

  // 4. 테크 / 비즈니스 / 업무 / 코딩
  scores.tech_business += countMatches(/(ai|인공지능|chatgpt|claude|gemini|코딩|개발자|프로그래밍|깃허브|github|스타트업|기획서|사업계획서)/g) * 15;
  scores.tech_business += countMatches(/(업무|재택|회의|보고서|프로젝트|출근|퇴근|회사|직장|커리어|노트북|생산성|자동화)/g) * 5;

  // 5. 요리 / 미식 / 카페
  scores.food_cooking += countMatches(/(레시피|요리사|셰프|원두|로스터리|베이킹|에스프레소|베이커리|맛집|브런치)/g) * 15;
  scores.food_cooking += countMatches(/(요리|식사|주방|커피|카페|디저트|저녁|점심|식탁|맛|플레이팅)/g) * 5;

  // 6. 금융 / 재테크 / 자산 관리
  scores.finance_life += countMatches(/(재테크|적금|예금|주식|투자|배당금|연봉|가계부|비상금|고정비|청약|환율)/g) * 15;
  scores.finance_life += countMatches(/(월급|생활비|소비|절약|계좌|통장|세금|이자|수익|자산)/g) * 5;

  // 7. 아웃도어 / 여행 / 힐링
  scores.outdoor_nature += countMatches(/(캠핑|텐트|피크닉|백패킹|차박|글램핑|솔숲|해수욕장|단풍|억새)/g) * 15;
  scores.outdoor_nature += countMatches(/(바다|해변|여행|힐링|휴식|공원|산책|노을|풍경|자연|숲|휴가)/g) * 5;

  let bestTheme = 'tech_business';
  let maxScore = 0;
  for (const [theme, score] of Object.entries(scores)) {
    if (score > maxScore) {
      maxScore = score;
      bestTheme = theme;
    }
  }

  // 매칭 스코어가 0이면 키워드 기반 기본 균등 분배
  if (maxScore === 0) {
    let hash = 0;
    for (let i = 0; i < text.length; i++) hash = (hash * 31 + text.charCodeAt(i)) & 0xffffffff;
    const themes = Object.keys(scores);
    bestTheme = themes[Math.abs(hash) % themes.length];
  }

  return bestTheme;
}

