/**
 * 테마 친화 키워드가 포함된 항목을 우선 선별하고, 없으면 전체 배열에서 랜덤 추출한다.
 */
function pickHarmonyItem(items, affinityKeywords = []) {
  if (!affinityKeywords || affinityKeywords.length === 0) {
    return items[Math.floor(Math.random() * items.length)];
  }
  const matched = items.filter(item => 
    affinityKeywords.some(kw => (item.name && item.name.includes(kw)) || (item.rule && item.rule.includes(kw)))
  );
  if (matched.length > 0) {
    return matched[Math.floor(Math.random() * matched.length)];
  }
  return items[Math.floor(Math.random() * items.length)];
}

/**
 * 1,000대 규칙 풀에서 본문의 맥락에 100% 개연성 있게 맞아떨어지는
 * 10대 차원 시각 연출 하모니 팩(Harmony Pack)을 합성한다.
 * @param {string} text 본문 텍스트
 * @returns {object} 테마와 완벽히 공명하는 10개 차원 시각 연출 지침
 */
export function generateDynamicSceneSeed(text = '') {
  const theme = detectThemeCluster(text);
  const affinity = THEME_AFFINITIES[theme] || THEME_AFFINITIES.tech_business;

  const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

  // 맥락 인지형 하모니 필터링 (장소, 동작, 소품, 의상, 조명)
  const location = pickHarmonyItem(LOCATIONS_SPACES_100, affinity.locations);
  const action = pickHarmonyItem(ACTIONS_GESTURES_100, affinity.actions);
  const prop = pickHarmonyItem(PROPS_OBJECTS_100, affinity.props);
  const fashion = pickHarmonyItem(FASHION_STYLING_100, affinity.fashions);
  const light = pickHarmonyItem(LIGHTING_ATMOSPHERE_100, affinity.lights);

  // 분위기를 북돋우는 서사적 매칭 (감정, 날씨, 텍스처, 앵글, 시간대)
  const emotion = pick(EMOTIONS_EXPRESSIONS_100);
  const weather = pick(WEATHER_SEASONS_100);
  const texture = pick(DEPTH_TEXTURE_100);
  const angle = pick(CAMERA_ANGLES_100);
  const time = pick(TIME_RHYTHM_100);

  // 한 편의 완성된 영화 콘티처럼 개연성 높은 서사 요약문(Narrative Summary) 조립
  const narrativeSummary = `[${location.name}] 배경에서 ${fashion.name} 스타일의 인물이 ${action.rule}. 얼굴에는 ${emotion.rule}이 가득하며, 손끝 또는 시선 가까이 ${prop.rule}이 자연스럽게 놓여 있다. ${light.rule}, ${weather.rule} 속에서 ${texture.rule}과 ${angle.rule}로 포착한 결정적 시네마틱 한 컷.`;

  return {
    theme,
    angle: angle.rule,
    action: action.rule,
    location: location.rule,
    emotion: emotion.rule,
    prop: prop.rule,
    light: light.rule,
    weather: weather.rule,
    fashion: fashion.rule,
    texture: texture.rule,
    time: time.rule,
    summary: narrativeSummary
  };
}

